const sources: Record<string, string> = {"code-example-1":"\"use client\";\n\nimport { useState } from \"react\";\nimport { IconArrowUpRight } from \"@tabler/icons-react\";\nimport { CodeBlock } from \"@/views/ui/_shared/CodeBlock\";\nimport { Tabs, TabsList, TabsTrigger } from \"@/components/ui/Tabs\";\nimport { Button } from \"@/components/ui/Button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\n\ninterface QuerySnippet {\n  value: string;\n  labelKey: string;\n  filename: string;\n  code: string;\n}\n\nconst QUERY_SNIPPETS: QuerySnippet[] = [\n  {\n    value: \"javascript\",\n    labelKey: \"codeExample1JavascriptLabel\",\n    filename: \"utils.js\",\n    code: `function fibonacci(n) {\n  if (n <= 1) return n;\n  return fibonacci(n - 1) + fibonacci(n - 2);\n}\n\nfunction debounce(func, delay) {\n  let timeoutId;\n  return (...args) => {\n    clearTimeout(timeoutId);\n    timeoutId = setTimeout(() => func(...args), delay);\n  };\n}\n\nconst memoize = (fn) => {\n  const cache = new Map();\n  return (...args) => {\n    const key = JSON.stringify(args);\n    if (cache.has(key)) return cache.get(key);\n    const result = fn(...args);\n    cache.set(key, result);\n    return result;\n  };\n};`,\n  },\n  {\n    value: \"python\",\n    labelKey: \"codeExample1PythonLabel\",\n    filename: \"utils.py\",\n    code: `def fibonacci(n):\n    if n <= 1:\n        return n\n    return fibonacci(n - 1) + fibonacci(n - 2)\n\ndef debounce(func, delay):\n    import threading\n    timer = None\n    def wrapper(*args, **kwargs):\n        nonlocal timer\n        if timer:\n            timer.cancel()\n        timer = threading.Timer(delay, func, args, kwargs)\n        timer.start()\n    return wrapper\n\ndef memoize(func):\n    cache = {}\n    def wrapper(*args):\n        if args not in cache:\n            cache[args] = func(*args)\n        return cache[args]\n    return wrapper`,\n  },\n  {\n    value: \"go\",\n    labelKey: \"codeExample1GoLabel\",\n    filename: \"utils.go\",\n    code: `package utils\n\nfunc Fibonacci(n int) int {\n    if n <= 1 {\n        return n\n    }\n    return Fibonacci(n-1) + Fibonacci(n-2)\n}\n\nfunc Map[T, U any](slice []T, transform func(T) U) []U {\n    result := make([]U, len(slice))\n    for i, item := range slice {\n        result[i] = transform(item)\n    }\n    return result\n}`,\n  },\n  {\n    value: \"ruby\",\n    labelKey: \"codeExample1RubyLabel\",\n    filename: \"utils.rb\",\n    code: `def fibonacci(n)\n  return n if n <= 1\n  fibonacci(n - 1) + fibonacci(n - 2)\nend\n\ndef debounce(delay, &block)\n  @timer&.cancel\n  @timer = Thread.new do\n    sleep(delay)\n    block.call\n  end\nend\n\ndef memoize(method_name)\n  cache = {}\n  define_method(method_name) do |*args|\n    cache[args] ||= super(*args)\n  end\nend`,\n  },\n];\n\nexport function TabbedQueryExamples() {\n  const t = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = t.codeExample;\n  const [selectedLanguage, setSelectedLanguage] = useState(\n    QUERY_SNIPPETS[0].value,\n  );\n  const activeSnippet =\n    QUERY_SNIPPETS.find((snippet) => snippet.value === selectedLanguage) ??\n    QUERY_SNIPPETS[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto w-full max-w-6xl px-6 lg:px-8\">\n        <div className=\"grid place-items-center gap-10 lg:grid-cols-2 lg:gap-0\">\n          <div className=\"flex flex-col gap-6 lg:pr-20\">\n            <span className=\"text-muted text-lg\">\n              {co[\"codeExample1Tagline\"]}\n            </span>\n            <h2 className=\"text-fg text-4xl font-bold tracking-tight md:text-5xl\">\n              {co[\"codeExample1Heading\"]}\n              <br />\n              <span className=\"text-muted\">\n                {co[\"codeExample1HeadingHighlight\"]}\n              </span>\n            </h2>\n            <p className=\"text-muted md:text-lg\">\n              {co[\"codeExample1Description\"]}\n            </p>\n            <Button\n              size=\"lg\"\n              className=\"w-fit\"\n              rightIcon={<IconArrowUpRight className=\"h-4 w-4\" />}\n            >\n              {co[\"codeExample1ButtonLabel\"]}\n            </Button>\n          </div>\n          <div className=\"flex w-full flex-col gap-1 overflow-hidden\">\n            <Tabs\n              defaultValue={QUERY_SNIPPETS[0].value}\n              onValueChange={setSelectedLanguage}\n            >\n              <TabsList className=\"h-10 w-full\">\n                {QUERY_SNIPPETS.map((snippet) => (\n                  <TabsTrigger key={snippet.value} value={snippet.value}>\n                    {co[snippet.labelKey]}\n                  </TabsTrigger>\n                ))}\n              </TabsList>\n            </Tabs>\n            <div className=\"border-border bg-surface flex items-center rounded-t-xl border border-b-0 px-4 py-2\">\n              <span className=\"text-muted font-mono text-xs\">\n                {activeSnippet.filename}\n              </span>\n            </div>\n            <CodeBlock code={activeSnippet.code} className=\"rounded-t-none\" />\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-2":"\"use client\";\n\nimport { useState } from \"react\";\nimport { IconArrowUpRight } from \"@tabler/icons-react\";\nimport { CodeBlock } from \"@/views/ui/_shared/CodeBlock\";\nimport { Tabs, TabsList, TabsTrigger } from \"@/components/ui/Tabs\";\nimport { Button } from \"@/components/ui/Button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\n\ninterface RequestSnippet {\n  value: string;\n  labelKey: string;\n  filename: string;\n  code: string;\n}\n\nconst REQUEST_SNIPPETS: RequestSnippet[] = [\n  {\n    value: \"javascript\",\n    labelKey: \"codeExample2JavascriptLabel\",\n    filename: \"http-request.js\",\n    code: `// Node.js HTTP request using fetch (Node 18+)\nconst response = await fetch('https://api.example.com/data', {\n  method: 'POST',\n  headers: {\n    'Content-Type': 'application/json',\n    'Authorization': 'Bearer your-token-here'\n  },\n  body: JSON.stringify({\n    name: 'John Doe',\n    email: 'john@example.com'\n  })\n});\n\nconst data = await response.json();\nconsole.log('Response:', data);\n\n// Alternative using axios\nconst axios = require('axios');\nconst response2 = await axios.post('https://api.example.com/data', {\n  name: 'John Doe',\n  email: 'john@example.com'\n}, {\n  headers: {\n    'Authorization': 'Bearer your-token-here'\n  }\n});`,\n  },\n  {\n    value: \"python\",\n    labelKey: \"codeExample2PythonLabel\",\n    filename: \"http_request.py\",\n    code: `# Python HTTP request using the requests library\nimport requests\n\nresponse = requests.post(\n    'https://api.example.com/data',\n    json={\n        'name': 'John Doe',\n        'email': 'john@example.com'\n    },\n    headers={\n        'Authorization': 'Bearer your-token-here'\n    }\n)\n\nprint(f'Status Code: {response.status_code}')\nprint(f'Response: {response.json()}')\n\n# Alternative using httpx (async)\nimport httpx\nimport asyncio\n\nasync def make_request():\n    async with httpx.AsyncClient() as client:\n        response = await client.post(\n            'https://api.example.com/data',\n            json={'name': 'John Doe', 'email': 'john@example.com'},\n            headers={'Authorization': 'Bearer your-token-here'}\n        )\n        return response.json()\n\n# asyncio.run(make_request())`,\n  },\n  {\n    value: \"go\",\n    labelKey: \"codeExample2GoLabel\",\n    filename: \"http_request.go\",\n    code: `package main\n\nimport (\n    \"bytes\"\n    \"encoding/json\"\n    \"fmt\"\n    \"io\"\n    \"net/http\"\n)\n\ntype User struct {\n    Name  string \\`json:\"name\"\\`\n    Email string \\`json:\"email\"\\`\n}\n\nfunc main() {\n    user := User{\n        Name:  \"John Doe\",\n        Email: \"john@example.com\",\n    }\n\n    jsonData, _ := json.Marshal(user)\n\n    req, _ := http.NewRequest(\"POST\", \"https://api.example.com/data\", bytes.NewBuffer(jsonData))\n    req.Header.Set(\"Content-Type\", \"application/json\")\n    req.Header.Set(\"Authorization\", \"Bearer your-token-here\")\n\n    client := &http.Client{}\n    resp, err := client.Do(req)\n    if err != nil {\n        fmt.Printf(\"Error: %v\\\\n\", err)\n        return\n    }\n    defer resp.Body.Close()\n\n    body, _ := io.ReadAll(resp.Body)\n    fmt.Printf(\"Status: %s\\\\n\", resp.Status)\n    fmt.Printf(\"Response: %s\\\\n\", string(body))\n}`,\n  },\n];\n\nexport function HttpRequestTabs() {\n  const t = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = t.codeExample;\n  const [selectedLanguage, setSelectedLanguage] = useState(\n    REQUEST_SNIPPETS[0].value,\n  );\n  const activeSnippet =\n    REQUEST_SNIPPETS.find((snippet) => snippet.value === selectedLanguage) ??\n    REQUEST_SNIPPETS[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto w-full max-w-6xl px-6 lg:px-8\">\n        <div className=\"bg-surface border-border relative rounded-3xl border p-6 lg:p-10\">\n          <div className=\"border-border bg-surface absolute -top-1 -left-1 size-[7px] rounded-full border\" />\n          <div className=\"border-border bg-surface absolute -top-1 -right-1 size-[7px] rounded-full border\" />\n          <div className=\"border-border bg-surface absolute -bottom-1 -left-1 size-[7px] rounded-full border\" />\n          <div className=\"border-border bg-surface absolute -right-1 -bottom-1 size-[7px] rounded-full border\" />\n          <div className=\"grid grid-cols-1 place-items-center gap-12 lg:grid-cols-2 lg:gap-6\">\n            <div className=\"relative flex flex-col gap-6\">\n              <h2 className=\"text-fg text-3xl font-semibold tracking-tight lg:text-5xl\">\n                {co[\"codeExample2Title\"]}\n              </h2>\n              <p className=\"text-muted lg:text-lg\">\n                {co[\"codeExample2Description\"]}\n              </p>\n              <Button\n                variant=\"outline\"\n                className=\"w-fit\"\n                rightIcon={<IconArrowUpRight className=\"h-4 w-4\" />}\n              >\n                {co[\"codeExample2DocsButton\"]}\n              </Button>\n            </div>\n            <div className=\"flex w-full flex-col gap-1 overflow-hidden\">\n              <Tabs\n                defaultValue={REQUEST_SNIPPETS[0].value}\n                onValueChange={setSelectedLanguage}\n              >\n                <TabsList className=\"grid h-10 w-full grid-cols-3\">\n                  {REQUEST_SNIPPETS.map((snippet) => (\n                    <TabsTrigger key={snippet.value} value={snippet.value}>\n                      {co[snippet.labelKey]}\n                    </TabsTrigger>\n                  ))}\n                </TabsList>\n              </Tabs>\n              <div className=\"border-border bg-surface flex items-center rounded-t-xl border border-b-0 px-4 py-2\">\n                <span className=\"text-muted font-mono text-xs\">\n                  {activeSnippet.filename}\n                </span>\n              </div>\n              <CodeBlock code={activeSnippet.code} className=\"rounded-t-none\" />\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-3":"\"use client\";\n\nimport { useState } from \"react\";\nimport { IconArrowRight } from \"@tabler/icons-react\";\nimport { CodeBlock } from \"@/views/ui/_shared/CodeBlock\";\nimport { Button } from \"@/components/ui/Button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\n\nconst USE_THEME_CODE = `import { useState, useEffect } from 'react';\n\nconst useTheme = () => {\n  const [theme, setTheme] = useState<'light' | 'dark'>('light');\n\n  useEffect(() => {\n    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';\n    if (savedTheme) {\n      setTheme(savedTheme);\n    }\n  }, []);\n\n  const toggleTheme = () => {\n    const newTheme = theme === 'light' ? 'dark' : 'light';\n    setTheme(newTheme);\n    localStorage.setItem('theme', newTheme);\n    document.documentElement.classList.toggle('dark');\n  };\n\n  return { theme, toggleTheme };\n};`;\n\nconst THEME_TOGGLE_CODE = `import { useTheme } from './useTheme';\n\nconst ThemeToggle = () => {\n  const { theme, toggleTheme } = useTheme();\n\n  return (\n    <div className=\"flex items-center gap-4\">\n      <span className=\"text-sm font-medium\">\n        Current theme: {theme}\n      </span>\n\n      <button\n        onClick={toggleTheme}\n        className=\"bg-brand text-brand-fg hover:bg-brand/90 rounded-lg px-4 py-2 transition-colors\"\n      >\n        Switch to {theme === 'light' ? 'Dark' : 'Light'}\n      </button>\n\n      <div\n        className={\n          theme === 'light'\n            ? 'border-border bg-warning size-8 rounded-full border-2'\n            : 'border-border bg-surface size-8 rounded-full border-2'\n        }\n      />\n    </div>\n  );\n};`;\n\nexport function ThemeHookDemo() {\n  const t = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = t.codeExample;\n  const [demoTheme, setDemoTheme] = useState<\"light\" | \"dark\">(\"light\");\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto w-full max-w-6xl px-6 lg:px-8\">\n        <div className=\"grid gap-20\">\n          <div className=\"grid place-items-center gap-10 lg:grid-cols-2\">\n            <div className=\"flex flex-col gap-4 lg:pr-10\">\n              <span className=\"text-muted mb-6 text-xs font-medium tracking-widest uppercase\">\n                {co[\"codeExample3HooksTag\"]}\n              </span>\n              <h2 className=\"text-fg text-4xl font-semibold tracking-tight\">\n                {co[\"codeExample3HooksHeading\"]}\n              </h2>\n              <p className=\"text-muted text-lg\">\n                {co[\"codeExample3HooksDescription\"]}\n              </p>\n              <Button\n                variant=\"outline\"\n                className=\"mt-4 w-fit\"\n                rightIcon={<IconArrowRight className=\"h-4 w-4\" />}\n              >\n                {co[\"codeExample3LearnMoreButton\"]}\n              </Button>\n            </div>\n            <div className=\"flex w-full flex-col gap-1 overflow-hidden\">\n              <div className=\"border-border bg-surface flex items-center rounded-t-xl border border-b-0 px-4 py-2\">\n                <span className=\"text-muted font-mono text-xs\">\n                  use-theme.ts\n                </span>\n              </div>\n              <CodeBlock code={USE_THEME_CODE} className=\"rounded-t-none\" />\n            </div>\n          </div>\n          <div className=\"grid place-items-center gap-10 lg:grid-cols-2\">\n            <div className=\"flex w-full flex-col gap-4 lg:order-none lg:pr-10\">\n              <div className=\"bg-surface border-border flex items-center justify-between gap-4 rounded-xl border p-4\">\n                <div className=\"flex items-center gap-3\">\n                  <span\n                    className={`size-6 rounded-full border-2 ${\n                      demoTheme === \"light\"\n                        ? \"border-border bg-brand\"\n                        : \"border-border bg-surface-hover\"\n                    }`}\n                  />\n                  <span className=\"text-fg text-sm font-medium\">\n                    {co[\"codeExample3CurrentThemeLabel\"]} {demoTheme}\n                  </span>\n                </div>\n                <Button\n                  size=\"sm\"\n                  onClick={() =>\n                    setDemoTheme(demoTheme === \"light\" ? \"dark\" : \"light\")\n                  }\n                >\n                  {demoTheme === \"light\"\n                    ? co[\"codeExample3SwitchToDarkButton\"]\n                    : co[\"codeExample3SwitchToLightButton\"]}\n                </Button>\n              </div>\n              <div className=\"flex w-full flex-col gap-1 overflow-hidden\">\n                <div className=\"border-border bg-surface flex items-center rounded-t-xl border border-b-0 px-4 py-2\">\n                  <span className=\"text-muted font-mono text-xs\">\n                    theme-toggle.tsx\n                  </span>\n                </div>\n                <CodeBlock\n                  code={THEME_TOGGLE_CODE}\n                  className=\"rounded-t-none\"\n                />\n              </div>\n            </div>\n            <div className=\"flex flex-col gap-4 lg:pl-10\">\n              <span className=\"text-muted mb-6 text-xs font-medium tracking-widest uppercase\">\n                {co[\"codeExample3ImplementationTag\"]}\n              </span>\n              <h2 className=\"text-fg text-4xl font-semibold tracking-tight\">\n                {co[\"codeExample3ImplementationHeading\"]}\n              </h2>\n              <p className=\"text-muted text-lg\">\n                {co[\"codeExample3ImplementationDescription\"]}\n              </p>\n              <Button\n                variant=\"outline\"\n                className=\"mt-4 w-fit\"\n                rightIcon={<IconArrowRight className=\"h-4 w-4\" />}\n              >\n                {co[\"codeExample3LearnMoreButton\"]}\n              </Button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-4":"\"use client\";\n\nimport { useState, type Dispatch, type SetStateAction } from \"react\";\nimport {\n  IconArrowRight,\n  IconChevronRight,\n  IconFile,\n  IconFolder,\n} from \"@tabler/icons-react\";\nimport { CodeBlock } from \"@/views/ui/_shared/CodeBlock\";\nimport { Button } from \"@/components/ui/Button\";\nimport { cn } from \"@/lib/cn\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\n\ninterface TreeNode {\n  id: string;\n  name: string;\n  type: \"folder\" | \"file\";\n  children?: TreeNode[];\n  code?: string;\n}\n\nconst FILE_TREE: TreeNode[] = [\n  {\n    id: \"src\",\n    name: \"src\",\n    type: \"folder\",\n    children: [\n      {\n        id: \"components\",\n        name: \"components\",\n        type: \"folder\",\n        children: [\n          {\n            id: \"ui\",\n            name: \"ui\",\n            type: \"folder\",\n            children: [\n              {\n                id: \"button\",\n                name: \"button.tsx\",\n                type: \"file\",\n                code: `import { cva, type VariantProps } from \"class-variance-authority\";\nimport { cn } from \"@/lib/cn\";\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-brand text-brand-fg shadow-xs hover:bg-brand/90\",\n        outline: \"border border-border bg-surface shadow-xs hover:bg-surface-hover\",\n        ghost: \"hover:bg-surface-hover\",\n        link: \"text-brand underline-offset-4 hover:underline\",\n      },\n      size: {\n        default: \"h-9 px-4 py-2\",\n        sm: \"h-8 rounded-md px-3\",\n        lg: \"h-10 rounded-md px-6\",\n        icon: \"size-9\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  },\n);\n\nfunction Button({\n  className,\n  variant,\n  size,\n  ...props\n}: React.ComponentProps<\"button\"> & VariantProps<typeof buttonVariants>) {\n  return (\n    <button\n      className={cn(buttonVariants({ variant, size, className }))}\n      {...props}\n    />\n  );\n}\n\nexport { Button, buttonVariants };`,\n              },\n            ],\n          },\n        ],\n      },\n      {\n        id: \"tsconfig\",\n        name: \"tsconfig.json\",\n        type: \"file\",\n        code: `{\n  \"compilerOptions\": {\n    \"target\": \"ES2017\",\n    \"lib\": [\"dom\", \"dom.iterable\", \"esnext\"],\n    \"allowJs\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"bundler\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"jsx\": \"preserve\",\n    \"paths\": {\n      \"@/*\": [\"./src/*\"]\n    }\n  },\n  \"include\": [\"next-env.d.ts\", \"**/*.ts\", \"**/*.tsx\", \".next/types/**/*.ts\"],\n  \"exclude\": [\"node_modules\"]\n}`,\n      },\n    ],\n  },\n];\n\nfunction findFile(nodes: TreeNode[], id: string): TreeNode | null {\n  for (const node of nodes) {\n    if (node.id === id) return node;\n    if (node.children) {\n      const found = findFile(node.children, id);\n      if (found) return found;\n    }\n  }\n  return null;\n}\n\nfunction handleToggle(\n  id: string,\n  setExpanded: Dispatch<SetStateAction<string[]>>,\n) {\n  setExpanded((prev) =>\n    prev.includes(id) ? prev.filter((entry) => entry !== id) : [...prev, id],\n  );\n}\n\nfunction renderNodes(\n  nodes: TreeNode[],\n  depth: number,\n  expanded: string[],\n  selectedId: string,\n  onSelect: (id: string) => void,\n  onToggle: (id: string) => void,\n) {\n  return nodes.map((node) => {\n    const isFolder = node.type === \"folder\";\n    const isExpanded = expanded.includes(node.id);\n    const isSelected = node.id === selectedId;\n    return (\n      <div key={node.id} className=\"flex flex-col\">\n        <button\n          type=\"button\"\n          onClick={() => (isFolder ? onToggle(node.id) : onSelect(node.id))}\n          aria-expanded={isFolder ? isExpanded : undefined}\n          className={cn(\n            \"flex w-full items-center gap-1.5 rounded-md px-2 py-1.5 text-left text-sm transition-colors\",\n            isSelected && !isFolder && \"bg-surface-hover text-fg\",\n            !isSelected && \"text-muted hover:bg-surface-hover hover:text-fg\",\n          )}\n          style={{ paddingLeft: `${depth * 14 + 8}px` }}\n        >\n          {isFolder ? (\n            <>\n              <IconChevronRight\n                className={cn(\n                  \"text-muted size-3.5 shrink-0 transition-transform\",\n                  isExpanded && \"rotate-90\",\n                )}\n              />\n              <IconFolder className=\"text-brand size-4 shrink-0\" />\n            </>\n          ) : (\n            <IconFile className=\"text-muted size-4 shrink-0\" />\n          )}\n          <span className=\"truncate\">{node.name}</span>\n        </button>\n        {isFolder && isExpanded && node.children\n          ? renderNodes(\n              node.children,\n              depth + 1,\n              expanded,\n              selectedId,\n              onSelect,\n              onToggle,\n            )\n          : null}\n      </div>\n    );\n  });\n}\n\nexport function FileTreePreview() {\n  const t = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = t.codeExample;\n  const [selectedId, setSelectedId] = useState(\"button\");\n  const [expanded, setExpanded] = useState<string[]>([\n    \"src\",\n    \"components\",\n    \"ui\",\n  ]);\n  const selectedFile = findFile(FILE_TREE, selectedId);\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto w-full max-w-6xl px-6 lg:px-8\">\n        <div className=\"mb-12 text-center\">\n          <span className=\"text-muted mb-6 block text-xs font-medium tracking-widest uppercase\">\n            {co[\"codeExample4Tag\"]}\n          </span>\n          <h2 className=\"text-fg mb-4 text-4xl font-semibold tracking-tight\">\n            {co[\"codeExample4Title\"]}\n          </h2>\n          <p className=\"text-muted mx-auto max-w-3xl text-lg\">\n            {co[\"codeExample4Description\"]}\n          </p>\n        </div>\n        <div className=\"grid lg:grid-cols-[300px_1fr]\">\n          <div className=\"border-border bg-surface border p-4 lg:rounded-l-xl lg:border-r-0\">\n            {renderNodes(\n              FILE_TREE,\n              0,\n              expanded,\n              selectedId,\n              setSelectedId,\n              (id) => handleToggle(id, setExpanded),\n            )}\n          </div>\n          <CodeBlock\n            code={selectedFile?.code ?? \"\"}\n            className=\"rounded-t-none lg:rounded-t-xl lg:rounded-l-none\"\n          />\n        </div>\n        <div className=\"mt-8 text-center\">\n          <Button\n            variant=\"outline\"\n            rightIcon={<IconArrowRight className=\"h-4 w-4\" />}\n          >\n            {co[\"codeExample4DocsButton\"]}\n          </Button>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-5":"\"use client\";\n\nimport { useState } from \"react\";\nimport {\n  IconApi,\n  IconBrandGraphql,\n  IconBrandJavascript,\n  IconBrandPython,\n  IconCode,\n  IconPlugConnected,\n} from \"@tabler/icons-react\";\nimport type { IconProps } from \"@tabler/icons-react\";\nimport { CodeBlock } from \"@/views/ui/_shared/CodeBlock\";\nimport { Tabs, TabsList, TabsTrigger } from \"@/components/ui/Tabs\";\nimport { cn } from \"@/lib/cn\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\n\ninterface ApiLanguage {\n  value: string;\n  labelKey: string;\n  filename: string;\n  code: string;\n}\n\ninterface ApiOption {\n  id: string;\n  icon: React.ComponentType<IconProps>;\n  titleKey: string;\n  descriptionKey: string;\n  languages: ApiLanguage[];\n}\n\nconst CODES: Record<string, string> = {\n  \"api-client.js\": `const res = await fetch('https://api.example.com/users', {\n  headers: { 'Authorization': 'Bearer your-api-key' },\n});\nconst users = await res.json();\nconsole.log('Users:', users);`,\n  \"api_client.py\": `import requests\n\nresponse = requests.get(\n    'https://api.example.com/users',\n    headers={'Authorization': 'Bearer your-api-key'},\n)\nprint(f\"Users: {response.json()}\")`,\n  \"api_client.rb\": `require 'httparty'\n\nresponse = HTTParty.get('https://api.example.com/users',\n  headers: { 'Authorization' => \"Bearer #{ENV['API_KEY']}\" })\nputs \"Users: #{response.parsed_response}\"`,\n  \"graphql-client.js\": `const GET_USERS = gql\\`\n  query GetUsers($limit: Int) {\n    users(limit: $limit) { id name email }\n  }\n\\`;\nconst { data, loading, error } = useQuery(GET_USERS, {\n  variables: { limit: 10 },\n});`,\n  \"graphql_client.py\": `from gql import gql, Client\nfrom gql.transport.aiohttp import AIOHTTPTransport\n\nclient = Client(\n    transport=AIOHTTPTransport(url=\"https://api.example.com/graphql\"),\n)\nGET_USERS = gql(\"{ users(limit: 10) { id name email } }\")\nprint(client.execute(GET_USERS))`,\n  \"graphql_client.rb\": `require 'graphql/client'\nrequire 'graphql/client/http'\n\nHTTP = GraphQL::Client::HTTP.new(\"https://api.example.com/graphql\")\nClient = GraphQL::Client.new(\n  schema: GraphQL::Client.load_schema(HTTP),\n  execute: HTTP,\n)\nGET_USERS = Client.parse(\"{ users(limit: 10) { id name email } }\")\nputs Client.query(GET_USERS).data.users`,\n  \"websocket-client.js\": `const ws = new WebSocket('wss://api.example.com/ws');\n\nws.onopen = () => ws.send(JSON.stringify({\n  type: 'subscribe', channel: 'notifications',\n}));\nws.onmessage = (event) =>\n  console.log('Received:', JSON.parse(event.data));`,\n  \"websocket_client.py\": `import asyncio, json, websockets\n\nasync def listen():\n    async with websockets.connect(\"wss://api.example.com/ws\") as ws:\n        await ws.send(json.dumps({\"type\": \"subscribe\", \"channel\": \"notifications\"}))\n        async for message in ws:\n            print(f\"Received: {json.loads(message)}\")\n\nasyncio.run(listen())`,\n  \"websocket_client.rb\": `require 'websocket-client-simple'\nrequire 'json'\n\nws = WebSocket::Client::Simple.connect('wss://api.example.com/ws')\nws.on :message do |msg|\n  puts \"Received: #{JSON.parse(msg.data)}\"\nend\nws.on :open do\n  ws.send(JSON.generate({ type: 'subscribe', channel: 'notifications' }))\nend\nsleep(60)`,\n};\n\nconst jsL = (filename: string): ApiLanguage => ({\n  value: \"javascript\",\n  labelKey: \"codeExample5JavascriptLabel\",\n  filename,\n  code: CODES[filename],\n});\nconst pyL = (filename: string): ApiLanguage => ({\n  value: \"python\",\n  labelKey: \"codeExample5PythonLabel\",\n  filename,\n  code: CODES[filename],\n});\nconst rbL = (filename: string): ApiLanguage => ({\n  value: \"ruby\",\n  labelKey: \"codeExample5RubyLabel\",\n  filename,\n  code: CODES[filename],\n});\n\nconst API_SNIPPETS: ApiOption[] = [\n  {\n    id: \"rest\",\n    icon: IconApi,\n    titleKey: \"codeExample5RestTitle\",\n    descriptionKey: \"codeExample5RestDescription\",\n    languages: [\n      jsL(\"api-client.js\"),\n      pyL(\"api_client.py\"),\n      rbL(\"api_client.rb\"),\n    ],\n  },\n  {\n    id: \"graphql\",\n    icon: IconBrandGraphql,\n    titleKey: \"codeExample5GraphqlTitle\",\n    descriptionKey: \"codeExample5GraphqlDescription\",\n    languages: [\n      jsL(\"graphql-client.js\"),\n      pyL(\"graphql_client.py\"),\n      rbL(\"graphql_client.rb\"),\n    ],\n  },\n  {\n    id: \"websocket\",\n    icon: IconPlugConnected,\n    titleKey: \"codeExample5WebsocketTitle\",\n    descriptionKey: \"codeExample5WebsocketDescription\",\n    languages: [\n      jsL(\"websocket-client.js\"),\n      pyL(\"websocket_client.py\"),\n      rbL(\"websocket_client.rb\"),\n    ],\n  },\n];\n\nconst LANGUAGE_ICONS: Record<string, React.ComponentType<IconProps>> = {\n  javascript: IconBrandJavascript,\n  python: IconBrandPython,\n  ruby: IconCode,\n};\n\nexport function ApiIntegrationSnippets() {\n  const t = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = t.codeExample;\n  const [selectedApi, setSelectedApi] = useState(API_SNIPPETS[0].id);\n  const [selectedLanguage, setSelectedLanguage] = useState(\"javascript\");\n  const activeApi =\n    API_SNIPPETS.find((api) => api.id === selectedApi) ?? API_SNIPPETS[0];\n  const activeLanguage =\n    activeApi.languages.find((l) => l.value === selectedLanguage) ??\n    activeApi.languages[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto w-full max-w-6xl px-6 lg:px-8\">\n        <div className=\"mx-auto mb-16 max-w-2xl text-center\">\n          <h2 className=\"text-fg mb-4 text-4xl font-bold tracking-tight md:text-5xl\">\n            {co[\"codeExample5Title\"]}\n          </h2>\n        </div>\n        <div className=\"grid gap-8 lg:grid-cols-3\">\n          <div className=\"lg:col-span-1\">\n            <div className=\"space-y-2\">\n              {API_SNIPPETS.map((api) => {\n                const ApiIcon = api.icon;\n                const isActive = api.id === selectedApi;\n                return (\n                  <button\n                    key={api.id}\n                    type=\"button\"\n                    onClick={() => setSelectedApi(api.id)}\n                    className={cn(\n                      \"w-full cursor-pointer rounded-lg p-4 text-left transition-all\",\n                      isActive\n                        ? \"bg-surface ring-border border-border ring-1\"\n                        : \"hover:bg-surface-hover\",\n                    )}\n                  >\n                    <div className=\"flex items-center gap-3\">\n                      <div className=\"bg-surface-hover rounded-lg p-2\">\n                        <ApiIcon className=\"text-brand size-5\" />\n                      </div>\n                      <div className=\"min-w-0 flex-1\">\n                        <h3 className=\"text-fg truncate text-sm font-medium\">\n                          {co[api.titleKey]}\n                        </h3>\n                        <p className=\"text-muted line-clamp-2 text-sm\">\n                          {co[api.descriptionKey]}\n                        </p>\n                      </div>\n                    </div>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n          <div className=\"min-w-0 lg:col-span-2\">\n            <div className=\"flex w-full flex-col gap-1 overflow-hidden\">\n              <Tabs\n                defaultValue=\"javascript\"\n                value={selectedLanguage}\n                onValueChange={setSelectedLanguage}\n              >\n                <TabsList className=\"grid h-10 w-full grid-cols-3\">\n                  {activeApi.languages.map((l) => {\n                    const LangIcon = LANGUAGE_ICONS[l.value];\n                    return (\n                      <TabsTrigger key={l.value} value={l.value}>\n                        {LangIcon && <LangIcon className=\"size-4\" />}\n                        <span className=\"hidden lg:inline\">\n                          {co[l.labelKey]}\n                        </span>\n                      </TabsTrigger>\n                    );\n                  })}\n                </TabsList>\n              </Tabs>\n              <div className=\"border-border bg-surface flex items-center rounded-t-xl border border-b-0 px-4 py-2\">\n                <span className=\"text-muted font-mono text-xs\">\n                  {activeLanguage.filename}\n                </span>\n              </div>\n              <CodeBlock\n                code={activeLanguage.code}\n                className=\"rounded-t-none\"\n              />\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-6":"\"use client\";\n\nimport { useState, type Dispatch, type SetStateAction } from \"react\";\nimport { IconCheck, IconCopy } from \"@tabler/icons-react\";\nimport { cn } from \"@/lib/cn\";\nimport { Button, IconButton } from \"@/components/ui/button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\nimport { useScrollFadeX } from \"@/hooks/useScrollFadeX\";\n\ninterface CodeExample6Snippet {\n  id: string;\n  nameKey: string;\n  benefitKey: string;\n  filename: string;\n  code: string;\n}\n\nconst CODE_EXAMPLE_6_SNIPPETS: CodeExample6Snippet[] = [\n  {\n    id: \"debounce\",\n    nameKey: \"codeExample6Card1Name\",\n    benefitKey: \"codeExample6Card1Benefit\",\n    filename: \"useDebounce.ts\",\n    code: `import { useEffect, useState } from \"react\";\n\nexport function useDebounce<T>(value: T, delay = 300) {\n  const [debounced, setDebounced] = useState(value);\n\n  useEffect(() => {\n    const timer = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(timer);\n  }, [value, delay]);\n\n  return debounced;\n}`,\n  },\n  {\n    id: \"local-storage\",\n    nameKey: \"codeExample6Card2Name\",\n    benefitKey: \"codeExample6Card2Benefit\",\n    filename: \"useLocalStorage.ts\",\n    code: `import { useCallback, useState } from \"react\";\n\nexport function useLocalStorage<T>(key: string, initial: T) {\n  const [stored, setStored] = useState<T>(() => {\n    try {\n      const raw = window.localStorage.getItem(key);\n      return raw ? JSON.parse(raw) : initial;\n    } catch {\n      return initial;\n    }\n  });\n\n  const setValue = useCallback(\n    (value: T) => {\n      setStored(value);\n      window.localStorage.setItem(key, JSON.stringify(value));\n    },\n    [key],\n  );\n\n  return [stored, setValue] as const;\n}`,\n  },\n  {\n    id: \"fetch\",\n    nameKey: \"codeExample6Card3Name\",\n    benefitKey: \"codeExample6Card3Benefit\",\n    filename: \"useFetch.ts\",\n    code: `import { useEffect, useState } from \"react\";\n\nexport function useFetch<T>(url: string) {\n  const [data, setData] = useState<T | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    fetch(url)\n      .then((res) => res.json())\n      .then(setData)\n      .finally(() => setLoading(false));\n  }, [url]);\n\n  return { data, loading };\n}`,\n  },\n];\n\nfunction handleCopy(\n  code: string,\n  setCopied: Dispatch<SetStateAction<boolean>>,\n) {\n  navigator.clipboard.writeText(code);\n  setCopied(true);\n  setTimeout(() => setCopied(false), 2000);\n}\n\nexport function SelectableHookSnippets() {\n  const scrollFadeRef = useScrollFadeX<HTMLPreElement>();\n  const m = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = m.codeExample;\n  const [activeId, setActiveId] = useState(CODE_EXAMPLE_6_SNIPPETS[0].id);\n  const [copied, setCopied] = useState(false);\n  const activeSnippet =\n    CODE_EXAMPLE_6_SNIPPETS.find((snippet) => snippet.id === activeId) ??\n    CODE_EXAMPLE_6_SNIPPETS[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto flex w-full max-w-6xl flex-col gap-10 px-6 lg:px-8\">\n        <div className=\"mx-auto flex max-w-2xl flex-col gap-3 text-center\">\n          <h2 className=\"text-3xl font-medium tracking-tight md:text-4xl\">\n            {co[\"codeExample6Title\"]}\n          </h2>\n          <p className=\"text-muted text-lg\">{co[\"codeExample6Description\"]}</p>\n        </div>\n        <div className=\"grid gap-3 md:grid-cols-3\">\n          {CODE_EXAMPLE_6_SNIPPETS.map((snippet) => (\n            <button\n              key={snippet.id}\n              type=\"button\"\n              onClick={() => setActiveId(snippet.id)}\n              className={cn(\n                \"flex flex-col gap-2 rounded-xl border p-5 text-left transition-colors\",\n                activeId === snippet.id\n                  ? \"border-brand bg-surface-hover\"\n                  : \"border-border bg-surface hover:bg-surface-hover\",\n              )}\n            >\n              <span className=\"text-base font-medium\">\n                {co[snippet.nameKey]}\n              </span>\n              <span className=\"text-muted text-sm\">\n                {co[snippet.benefitKey]}\n              </span>\n              <span className=\"text-muted font-mono text-xs\">\n                {snippet.filename}\n              </span>\n            </button>\n          ))}\n        </div>\n        <div className=\"border-border bg-surface overflow-hidden rounded-2xl border\">\n          <div className=\"border-border flex items-center justify-between border-b px-4 py-3\">\n            <span className=\"text-muted font-mono text-xs\">\n              {activeSnippet.filename}\n            </span>\n            <IconButton\n              icon={copied ? <IconCheck size={14} /> : <IconCopy size={14} />}\n              variant=\"ghost\"\n              size=\"icon-xs\"\n              label={\n                copied\n                  ? co[\"codeExample6CopiedLabel\"]\n                  : co[\"codeExample6CopyLabel\"]\n              }\n              onClick={() => handleCopy(activeSnippet.code, setCopied)}\n            />\n          </div>\n          <pre\n            ref={scrollFadeRef}\n            className=\"overflow-x-auto p-4 font-mono text-sm leading-relaxed\"\n          >\n            <code>{activeSnippet.code}</code>\n          </pre>\n        </div>\n        <Button variant=\"outline\" className=\"w-full\">\n          {co[\"codeExample6Cta\"]}\n        </Button>\n      </div>\n    </section>\n  );\n}\n","code-example-11":"\"use client\";\n\nimport {\n  useState,\n  type Dispatch,\n  type SetStateAction,\n  type ReactNode,\n} from \"react\";\nimport {\n  IconBrandGithub,\n  IconBrandGolang,\n  IconBrandNodejs,\n  IconBrandPython,\n  IconBrandRust,\n  IconCheck,\n  IconCopy,\n} from \"@tabler/icons-react\";\nimport { cn } from \"@/lib/cn\";\nimport { Tabs, TabsList, TabsTrigger } from \"@/components/ui/tabs\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n} from \"@/components/ui/select\";\nimport { Button, IconButton } from \"@/components/ui/button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\nimport { useScrollFadeX } from \"@/hooks/useScrollFadeX\";\n\ninterface CodeExample11Framework {\n  id: string;\n  labelKey: string;\n  filename: string;\n  code: string;\n}\n\ninterface CodeExample11Language {\n  id: string;\n  nameKey: string;\n  icon: ReactNode;\n  frameworks: CodeExample11Framework[];\n}\n\nconst CODE_EXAMPLE_11_LANGUAGES: CodeExample11Language[] = [\n  {\n    id: \"node\",\n    nameKey: \"codeExample11LanguageNode\",\n    icon: <IconBrandNodejs size={20} />,\n    frameworks: [\n      {\n        id: \"prisma\",\n        labelKey: \"codeExample11FrameworkPrisma\",\n        filename: \"prisma/schema.prisma\",\n        code: `datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id    Int    @id @default(autoincrement())\n  email String @unique\n  name  String?\n}`,\n      },\n      {\n        id: \"node-pg\",\n        labelKey: \"codeExample11FrameworkNodePostgres\",\n        filename: \"src/db.ts\",\n        code: `import { Pool } from \"pg\";\n\nconst pool = new Pool({\n  connectionString: process.env.DATABASE_URL,\n});\n\nconst result = await pool.query(\n  \"SELECT * FROM users WHERE email = $1\",\n  [\"ada@example.com\"],\n);\n\nconsole.log(result.rows);`,\n      },\n    ],\n  },\n  {\n    id: \"python\",\n    nameKey: \"codeExample11LanguagePython\",\n    icon: <IconBrandPython size={20} />,\n    frameworks: [\n      {\n        id: \"psycopg\",\n        labelKey: \"codeExample11FrameworkPsycopg\",\n        filename: \"src/db.py\",\n        code: `import psycopg\n\nconn = psycopg.connect(\"postgresql://localhost/app\")\ncur = conn.cursor()\ncur.execute(\n    \"SELECT * FROM users WHERE email = %s\",\n    (\"ada@example.com\",),\n)\nrows = cur.fetchall()\nconn.close()`,\n      },\n      {\n        id: \"asyncpg\",\n        labelKey: \"codeExample11FrameworkAsyncpg\",\n        filename: \"src/db_async.py\",\n        code: `import asyncio\nimport asyncpg\n\n\nasync def main():\n    conn = await asyncpg.connect(\"postgresql://localhost/app\")\n    rows = await conn.fetch(\n        \"SELECT * FROM users WHERE email = $1\",\n        \"ada@example.com\",\n    )\n    await conn.close()\n\n\nasyncio.run(main())`,\n      },\n    ],\n  },\n  {\n    id: \"go\",\n    nameKey: \"codeExample11LanguageGo\",\n    icon: <IconBrandGolang size={20} />,\n    frameworks: [\n      {\n        id: \"go-sql\",\n        labelKey: \"codeExample11FrameworkGoSql\",\n        filename: \"db.go\",\n        code: `package main\n\nimport (\n\t\"database/sql\"\n\t\"fmt\"\n\n\t_ \"github.com/lib/pq\"\n)\n\nfunc main() {\n\tdb, _ := sql.Open(\"postgres\", \"postgres://localhost/app?sslmode=disable\")\n\tdefer db.Close()\n\n\trows, _ := db.Query(\"SELECT * FROM users WHERE email = $1\", \"ada@example.com\")\n\tfmt.Println(rows)\n}`,\n      },\n      {\n        id: \"pgx\",\n        labelKey: \"codeExample11FrameworkPgx\",\n        filename: \"db_pool.go\",\n        code: `package main\n\nimport (\n\t\"context\"\n\t\"fmt\"\n\n\t\"github.com/jackc/pgx/v5/pgxpool\"\n)\n\nfunc main() {\n\tctx := context.Background()\n\tpool, _ := pgxpool.New(ctx, \"postgres://localhost/app\")\n\tdefer pool.Close()\n\n\trows, _ := pool.Query(ctx, \"SELECT * FROM users WHERE email = $1\", \"ada@example.com\")\n\tfmt.Println(rows)\n}`,\n      },\n    ],\n  },\n  {\n    id: \"rust\",\n    nameKey: \"codeExample11LanguageRust\",\n    icon: <IconBrandRust size={20} />,\n    frameworks: [\n      {\n        id: \"sqlx\",\n        labelKey: \"codeExample11FrameworkSqlx\",\n        filename: \"src/main.rs\",\n        code: `use sqlx::postgres::{PgPool, PgPoolOptions};\n\n#[tokio::main]\nasync fn main() -> Result<(), sqlx::Error> {\n    let pool = PgPoolOptions::new()\n        .max_connections(5)\n        .connect(\"postgres://localhost/app\")\n        .await?;\n\n    let rows = sqlx::query(\"SELECT * FROM users WHERE email = $1\")\n        .bind(\"ada@example.com\")\n        .fetch_all(&pool)\n        .await?;\n\n    println!(\"{:?}\", rows);\n    Ok(())\n}`,\n      },\n      {\n        id: \"tokio-postgres\",\n        labelKey: \"codeExample11FrameworkTokioPostgres\",\n        filename: \"src/db.rs\",\n        code: `use tokio_postgres::NoTls;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let (client, connection) =\n        tokio_postgres::connect(\"postgres://localhost/app\", NoTls).await?;\n\n    tokio::spawn(async move {\n        if let Err(e) = connection.await {\n            eprintln!(\"connection error: {}\", e);\n        }\n    });\n\n    let rows = client\n        .query(\"SELECT * FROM users WHERE email = $1\", &[&\"ada@example.com\"])\n        .await?;\n\n    println!(\"{:?}\", rows);\n    Ok(())\n}`,\n      },\n    ],\n  },\n];\n\nfunction handleLanguageChange(\n  languageId: string,\n  setLanguageId: Dispatch<SetStateAction<string>>,\n  setFrameworkId: Dispatch<SetStateAction<string>>,\n) {\n  setLanguageId(languageId);\n  const language = CODE_EXAMPLE_11_LANGUAGES.find((l) => l.id === languageId);\n  setFrameworkId(language?.frameworks[0]?.id ?? \"\");\n}\n\nfunction handleCopy(\n  code: string,\n  setCopied: Dispatch<SetStateAction<boolean>>,\n) {\n  navigator.clipboard.writeText(code);\n  setCopied(true);\n  setTimeout(() => setCopied(false), 2000);\n}\n\nexport function DatabaseExamplesStack() {\n  const scrollFadeRef = useScrollFadeX<HTMLPreElement>();\n  const m = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = m.codeExample;\n  const [languageId, setLanguageId] = useState(\"node\");\n  const [frameworkId, setFrameworkId] = useState(\"prisma\");\n  const [copied, setCopied] = useState(false);\n\n  const activeLanguage =\n    CODE_EXAMPLE_11_LANGUAGES.find((language) => language.id === languageId) ??\n    CODE_EXAMPLE_11_LANGUAGES[0];\n  const activeFramework =\n    activeLanguage.frameworks.find(\n      (framework) => framework.id === frameworkId,\n    ) ?? activeLanguage.frameworks[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto flex w-full max-w-6xl flex-col items-center gap-8 px-6 lg:px-8\">\n        <div className=\"flex max-w-2xl flex-col items-center gap-3 text-center\">\n          <h2 className=\"text-3xl font-medium tracking-tight md:text-4xl\">\n            {co[\"codeExample11Title\"]}\n          </h2>\n          <p className=\"text-muted text-lg\">{co[\"codeExample11Description\"]}</p>\n        </div>\n        <div className=\"flex flex-wrap justify-center gap-3\">\n          {CODE_EXAMPLE_11_LANGUAGES.map((language) => (\n            <button\n              key={language.id}\n              type=\"button\"\n              onClick={() =>\n                handleLanguageChange(language.id, setLanguageId, setFrameworkId)\n              }\n              className={cn(\n                \"flex items-center gap-3 rounded-xl border px-4 py-2.5 transition-colors\",\n                languageId === language.id\n                  ? \"border-brand bg-surface-hover\"\n                  : \"border-border bg-surface hover:bg-surface-hover\",\n              )}\n            >\n              <span className=\"border-border bg-surface flex size-9 items-center justify-center rounded-lg border\">\n                {language.icon}\n              </span>\n              <span\n                className={cn(\n                  \"text-sm font-medium\",\n                  languageId === language.id ? \"text-fg\" : \"text-muted\",\n                )}\n              >\n                {co[language.nameKey]}\n              </span>\n            </button>\n          ))}\n        </div>\n        <div className=\"hidden md:block\">\n          <Tabs value={frameworkId} onValueChange={setFrameworkId}>\n            <TabsList>\n              {activeLanguage.frameworks.map((framework) => (\n                <TabsTrigger\n                  key={framework.id}\n                  value={framework.id}\n                  className=\"text-sm\"\n                >\n                  {co[framework.labelKey]}\n                </TabsTrigger>\n              ))}\n            </TabsList>\n          </Tabs>\n        </div>\n        <div className=\"w-full md:hidden\">\n          <Select\n            value={frameworkId}\n            onValueChange={setFrameworkId}\n            name=\"code-example-11-framework\"\n          >\n            <SelectTrigger className=\"w-full\">\n              {co[activeFramework.labelKey]}\n            </SelectTrigger>\n            <SelectContent>\n              {activeLanguage.frameworks.map((framework) => (\n                <SelectItem key={framework.id} value={framework.id}>\n                  {co[framework.labelKey]}\n                </SelectItem>\n              ))}\n            </SelectContent>\n          </Select>\n        </div>\n        <div className=\"border-border bg-surface w-full overflow-hidden rounded-2xl border\">\n          <div className=\"border-border flex items-center justify-between border-b px-4 py-3\">\n            <span className=\"text-muted font-mono text-xs\">\n              {activeFramework.filename}\n            </span>\n            <IconButton\n              icon={copied ? <IconCheck size={14} /> : <IconCopy size={14} />}\n              variant=\"ghost\"\n              size=\"icon-xs\"\n              label={\n                copied\n                  ? co[\"codeExample11CopiedLabel\"]\n                  : co[\"codeExample11CopyLabel\"]\n              }\n              onClick={() => handleCopy(activeFramework.code, setCopied)}\n            />\n          </div>\n          <pre\n            ref={scrollFadeRef}\n            className=\"overflow-x-auto p-4 font-mono text-sm leading-relaxed\"\n          >\n            <code>{activeFramework.code}</code>\n          </pre>\n        </div>\n        <div className=\"flex w-full max-w-md flex-col items-center gap-4\">\n          <div className=\"border-border w-full border-t\" />\n          <Button variant=\"link\" className=\"gap-2\">\n            <IconBrandGithub size={16} />\n            {co[\"codeExample11Docs\"]}\n          </Button>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-14":"\"use client\";\n\nimport {\n  useState,\n  type Dispatch,\n  type SetStateAction,\n  type ReactNode,\n} from \"react\";\nimport {\n  IconCheck,\n  IconCopy,\n  IconFolder,\n  IconPencil,\n  IconTrash,\n  IconUpload,\n} from \"@tabler/icons-react\";\nimport { Accordion, AccordionItemComplex } from \"@/components/ui/accordion\";\nimport { Button, IconButton } from \"@/components/ui/button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\nimport { useScrollFadeX } from \"@/hooks/useScrollFadeX\";\n\ninterface CodeExample14Operation {\n  id: string;\n  icon: ReactNode;\n  titleKey: string;\n  contentKey: string;\n  filename: string;\n  code: string;\n}\n\nconst CODE_EXAMPLE_14_OPERATIONS: CodeExample14Operation[] = [\n  {\n    id: \"create\",\n    icon: <IconUpload size={16} />,\n    titleKey: \"codeExample14CreateTitle\",\n    contentKey: \"codeExample14CreateDescription\",\n    filename: \"file-service.ts\",\n    code: `import { createFile } from \"@acme/storage\";\n\nconst file = await createFile({\n  name: \"report.pdf\",\n  folderId: \"folder_8f2a\",\n  content: Buffer.from(\"Q4 earnings report\"),\n  public: false,\n});\n\nconsole.log(file.id, file.size);`,\n  },\n  {\n    id: \"update\",\n    icon: <IconPencil size={16} />,\n    titleKey: \"codeExample14UpdateTitle\",\n    contentKey: \"codeExample14UpdateDescription\",\n    filename: \"file-service.ts\",\n    code: `import { updateFile } from \"@acme/storage\";\n\nconst file = await updateFile(\"file_1c93\", {\n  name: \"report-final.pdf\",\n  folderId: \"folder_8f2a\",\n  public: true,\n});\n\nconsole.log(file.updatedAt);`,\n  },\n  {\n    id: \"delete\",\n    icon: <IconTrash size={16} />,\n    titleKey: \"codeExample14DeleteTitle\",\n    contentKey: \"codeExample14DeleteDescription\",\n    filename: \"file-service.ts\",\n    code: `import { deleteFile } from \"@acme/storage\";\n\nawait deleteFile(\"file_1c93\");\n\nconsole.log(\"File moved to trash\");`,\n  },\n];\n\nfunction handleCopy(\n  code: string,\n  setCopied: Dispatch<SetStateAction<boolean>>,\n) {\n  navigator.clipboard.writeText(code);\n  setCopied(true);\n  setTimeout(() => setCopied(false), 2000);\n}\n\nexport function FileOpsAccordion() {\n  const scrollFadeRef = useScrollFadeX<HTMLPreElement>();\n  const m = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = m.codeExample;\n  const [activeOperationId, setActiveOperationId] = useState(\"create\");\n  const [copied, setCopied] = useState(false);\n\n  const activeOperation =\n    CODE_EXAMPLE_14_OPERATIONS.find(\n      (operation) => operation.id === activeOperationId,\n    ) ?? CODE_EXAMPLE_14_OPERATIONS[0];\n\n  return (\n    <section className=\"relative w-full py-16 lg:py-24\">\n      <div className=\"bg-brand/5 pointer-events-none absolute inset-x-0 top-0 mx-auto h-64 w-[36rem] max-w-full rounded-full blur-3xl\" />\n      <div className=\"relative mx-auto flex w-full max-w-6xl flex-col gap-10 px-6 lg:px-8\">\n        <div className=\"mx-auto flex max-w-2xl flex-col items-center gap-4 text-center\">\n          <span className=\"border-border bg-surface text-muted inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-medium\">\n            <IconFolder size={14} className=\"text-brand\" />\n            {co[\"codeExample14Badge\"]}\n          </span>\n          <h2 className=\"text-3xl font-medium tracking-tight md:text-4xl\">\n            {co[\"codeExample14Title\"]}\n          </h2>\n          <p className=\"text-muted text-lg\">{co[\"codeExample14Description\"]}</p>\n          <div className=\"mt-2 flex flex-wrap justify-center gap-3\">\n            <Button>{co[\"codeExample14PrimaryButton\"]}</Button>\n            <Button variant=\"outline\">\n              {co[\"codeExample14SecondaryButton\"]}\n            </Button>\n          </div>\n        </div>\n        <div className=\"grid items-start gap-6 lg:grid-cols-2\">\n          <Accordion\n            type=\"single\"\n            collapsible\n            value={activeOperationId}\n            onValueChange={setActiveOperationId}\n            className=\"w-full\"\n          >\n            {CODE_EXAMPLE_14_OPERATIONS.map((operation) => (\n              <AccordionItemComplex\n                key={operation.id}\n                value={operation.id}\n                leftSlot={\n                  <div className=\"border-border bg-surface flex size-9 items-center justify-center rounded-lg border\">\n                    <span className=\"text-brand\">{operation.icon}</span>\n                  </div>\n                }\n                centerSlot={\n                  <span className=\"font-medium\">{co[operation.titleKey]}</span>\n                }\n                content={\n                  <p className=\"text-muted\">{co[operation.contentKey]}</p>\n                }\n              />\n            ))}\n          </Accordion>\n          <div className=\"border-border bg-surface overflow-hidden rounded-2xl border\">\n            <div className=\"border-border flex items-center justify-between border-b px-4 py-3\">\n              <span className=\"text-muted font-mono text-xs\">\n                {activeOperation.filename}\n              </span>\n              <IconButton\n                icon={copied ? <IconCheck size={14} /> : <IconCopy size={14} />}\n                variant=\"ghost\"\n                size=\"icon-xs\"\n                label={\n                  copied\n                    ? co[\"codeExample14CopiedLabel\"]\n                    : co[\"codeExample14CopyLabel\"]\n                }\n                onClick={() => handleCopy(activeOperation.code, setCopied)}\n              />\n            </div>\n            <pre\n              ref={scrollFadeRef}\n              className=\"overflow-x-auto p-4 font-mono text-sm leading-relaxed\"\n            >\n              <code>{activeOperation.code}</code>\n            </pre>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n","code-example-16":"\"use client\";\n\nimport { useState } from \"react\";\nimport { Tabs, TabsList, TabsTrigger } from \"@/components/ui/tabs\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n} from \"@/components/ui/select\";\nimport { Button } from \"@/components/ui/button\";\nimport { useMessages } from \"@/lib/i18n/MessagesProvider\";\nimport type { PagesWithCodeExampleMessages } from \"@/types/pages/code-example/CodeExampleMessages-types\";\nimport { useScrollFadeX } from \"@/hooks/useScrollFadeX\";\n\ninterface CodeExample16Mode {\n  id: string;\n  labelKey: string;\n  filename: string;\n  code: string;\n}\n\nconst CODE_EXAMPLE_16_MODES: CodeExample16Mode[] = [\n  {\n    id: \"server\",\n    labelKey: \"codeExample16ModeServer\",\n    filename: \"server.ts\",\n    code: `import { MetricsClient } from \"@acme/metrics\";\n\nconst metrics = new MetricsClient({ dashboardId: \"dash_42\" });\n\nexport async function loadPageMetrics() {\n  return metrics.query({\n    range: \"last-30-days\",\n    series: [\"pageviews\", \"sessions\"],\n  });\n}`,\n  },\n  {\n    id: \"hook\",\n    labelKey: \"codeExample16ModeHook\",\n    filename: \"use-page-metrics.ts\",\n    code: `import { useQuery } from \"@tanstack/react-query\";\nimport { metricsClient } from \"./metrics-client\";\n\nexport function usePageMetrics() {\n  return useQuery({\n    queryKey: [\"metrics\", \"page\", \"last-30-days\"],\n    queryFn: () =>\n      metricsClient.query({\n        range: \"last-30-days\",\n        series: [\"pageviews\", \"sessions\"],\n      }),\n  });\n}`,\n  },\n  {\n    id: \"react\",\n    labelKey: \"codeExample16ModeReact\",\n    filename: \"PageMetrics.tsx\",\n    code: `import { usePageMetrics } from \"./use-page-metrics\";\n\nexport function PageMetrics() {\n  const { data, isLoading } = usePageMetrics();\n\n  if (isLoading) return <p>Loading metrics...</p>;\n\n  return (\n    <section>\n      <h2>Page overview</h2>\n      <p>{data?.pageviews.toLocaleString()} pageviews</p>\n      <p>{data?.sessions.toLocaleString()} sessions</p>\n    </section>\n  );\n}`,\n  },\n];\n\nexport function AnalyticsSnippetModes() {\n  const scrollFadeRef = useScrollFadeX<HTMLPreElement>();\n  const m = useMessages(\"pages\") as unknown as PagesWithCodeExampleMessages;\n  const co = m.codeExample;\n  const [modeId, setModeId] = useState(CODE_EXAMPLE_16_MODES[0].id);\n\n  const activeMode =\n    CODE_EXAMPLE_16_MODES.find((mode) => mode.id === modeId) ??\n    CODE_EXAMPLE_16_MODES[0];\n\n  return (\n    <section className=\"w-full py-16 lg:py-24\">\n      <div className=\"mx-auto flex w-full max-w-6xl flex-col items-center gap-8 px-6 lg:px-8\">\n        <div className=\"flex max-w-2xl flex-col items-center gap-3 text-center\">\n          <span className=\"text-brand text-xs font-semibold tracking-widest uppercase\">\n            {co[\"codeExample16Eyebrow\"]}\n          </span>\n          <h2 className=\"text-3xl font-medium tracking-tight md:text-4xl\">\n            {co[\"codeExample16Title\"]}\n          </h2>\n          <p className=\"text-muted text-lg\">{co[\"codeExample16Description\"]}</p>\n          <Button className=\"mt-2\">{co[\"codeExample16Cta\"]}</Button>\n        </div>\n        <div className=\"border-border bg-surface w-full overflow-hidden rounded-2xl border\">\n          <div className=\"border-border flex flex-wrap items-center justify-between gap-3 border-b px-4 py-3\">\n            <span className=\"text-muted font-mono text-xs\">\n              {activeMode.filename}\n            </span>\n            <div className=\"flex items-center gap-3\">\n              <Tabs\n                value={modeId}\n                onValueChange={setModeId}\n                className=\"hidden sm:block\"\n              >\n                <TabsList>\n                  {CODE_EXAMPLE_16_MODES.map((mode) => (\n                    <TabsTrigger\n                      key={mode.id}\n                      value={mode.id}\n                      className=\"text-sm\"\n                    >\n                      {co[mode.labelKey]}\n                    </TabsTrigger>\n                  ))}\n                </TabsList>\n              </Tabs>\n              <div className=\"sm:hidden\">\n                <Select\n                  value={modeId}\n                  onValueChange={setModeId}\n                  name=\"code-example-16-mode\"\n                >\n                  <SelectTrigger className=\"w-44\">\n                    {co[activeMode.labelKey]}\n                  </SelectTrigger>\n                  <SelectContent>\n                    {CODE_EXAMPLE_16_MODES.map((mode) => (\n                      <SelectItem key={mode.id} value={mode.id}>\n                        {co[mode.labelKey]}\n                      </SelectItem>\n                    ))}\n                  </SelectContent>\n                </Select>\n              </div>\n            </div>\n          </div>\n          <pre\n            ref={scrollFadeRef}\n            className=\"overflow-x-auto p-4 font-mono text-sm leading-relaxed\"\n          >\n            <code>{activeMode.code}</code>\n          </pre>\n        </div>\n      </div>\n    </section>\n  );\n}\n"};
export default sources;
